pub fn make_pair(a: f32, b: f32) -> Vec<f32> {
    // Exactly two elements, preserving order, accepting any f32 including NaN/Inf.
    vec![a, b]
}

pub fn lagline(off: f32, scl: f32) -> Vec<f32> {
    // Same requirement: return a 2-element vector in the same order.
    vec![off, scl]
}

